#[derive(Default)]struct Stats{cases:u64,corrections:[u64;2],max_high:u64,max_low:u64,max_q_bits:u64,examples:[Option<Value>;2]}
fn digits<const N:usize>(n:&BigUint,w:u32)->[u64;N]{let mask=(BigUint::one()<<w)-1u8;let out=core::array::from_fn(|i|((n>>(i as u32*w))& &mask).to_u64().unwrap());assert_eq!(n>>(N as u32*w),BigUint::zero());out}
fn integer(a:&[u64],w:u32)->BigUint{a.iter().rev().fold(BigUint::zero(),|n,&v|(n<<w)+v)}
fn sub(a:[u64;5],b:[u64;5],w:u32)->([u64;5],i128){let mask=(1i128<<w)-1;let mut carry=0i128;let out=core::array::from_fn(|j|{let v=a[j]as i128-b[j]as i128+carry;carry=v>>w;(v&mask)as u64});(out,carry)}
