fn prepare(b:[u64;5],mu:[u64;6],p:[u64;5],w:u32,s:&mut Stats)->([u64;5],[u64;5],[u64;5],[u64;5],usize){let mask=(1u64<<w)-1;assert!(b.iter().chain(mu.iter()).chain(p.iter()).all(|&v|v<=mask));let mut h=[0u64;7];let mut high_ops=0;for i in 0..5{for j in 0..6{let k=i+j;let product=b[i]as u128*mu[j]as u128;if k==3{h[0]=h[0].checked_add((product>>w)as u64).unwrap();high_ops+=1;}else if k>=4{h[k-4]=h[k-4].checked_add((product&mask as u128)as u64).unwrap();h[k-3]=h[k-3].checked_add((product>>w)as u64).unwrap();high_ops+=2;}}}assert_eq!(high_ops,44);for j in 0..6{s.max_high=s.max_high.max(h[j]);h[j+1]=h[j+1].checked_add(h[j]>>w).unwrap();h[j]&=mask;}assert_eq!(h[6],0);let q0=[h[1],h[2],h[3],h[4],h[5]];let mut product=[0u64;5];let mut low_ops=0;for i in 0..5{for j in 0..5-i{let k=i+j;let v=q0[i]as u128*p[j]as u128;product[k]=product[k].checked_add((v&mask as u128)as u64).unwrap();low_ops+=1;if k<4{product[k+1]=product[k+1].checked_add((v>>w)as u64).unwrap();low_ops+=1;}}}assert_eq!(low_ops,25);let mut carry=0u64;for digit in &mut product{let v=digit.checked_add(carry).unwrap();s.max_low=s.max_low.max(v);*digit=v&mask;carry=v>>w;}let(d0,_)=sub([0;5],product,w);let(candidate,borrow)=sub(d0,p,w);assert!(borrow==0||borrow== -1);let correction=usize::from(borrow==0);let d=if correction==1{candidate}else{d0};let mut q=q0;if correction==1{let mut carry=1;for digit in &mut q{let v=*digit+carry;*digit=v&mask;carry=v>>w;}assert_eq!(carry,0);}assert!(q.iter().chain(d.iter()).all(|&v|v<=mask));(q,d,q0,d0,correction)}
fn cases(p:&BigUint,r:&BigUint,w:u32)->Vec<BigUint>{let mut v=BTreeSet::new();let mut add=|n:BigUint|{if &n<p{v.insert(n);}};for n in[0u64,1,2,3,15,16,17,31,32,33,255,256,257]{add(n.into());}for k in 0..=260u32{let pow=BigUint::one()<<k;for delta in[-2i64,-1,0,1,2]{let n=if delta<0{if pow<BigUint::from((-delta)as u64){continue;} &pow-(-delta)as u64}else{&pow+delta as u64};add(n.clone());let center=&n*p/r;for d in[-2i64,-1,0,1,2]{if d<0&&center<BigUint::from((-d)as u64){continue;}let b=if d<0{&center-(-d)as u64}else{&center+d as u64};add(b);}}}for n in[1u64,2,3,15,16,17,31,32,33,255,256,257]{add(p-n);}for j in 1..5{let edge=BigUint::one()<<(w*j);for n in[1u64,2,3]{if p>&(&edge+BigUint::from(n)){add(p-&edge-n);add(p-&edge+n);}}}for i in 0..8192u64{let mut h=Sha256::new();h.update(b"fft-column-fast-quotient-preparation176");h.update(w.to_le_bytes());h.update(i.to_le_bytes());h.update(p.to_bytes_le());add(BigUint::from_bytes_le(&h.finalize())%p);}v.into_iter().collect()}
fn run(name:&str,p:BigUint,w:u32,exhaust:bool)->Value{let r=BigUint::one()<<(5*w);let bbase=BigUint::one()<<w;assert!(p> &r/&bbase&&p<(&r>>1));assert!(&p*&bbase+&r*8u8 < &r*&bbase);let mu=&r*&r/&p;let md=digits::<6>(&mu,w);let pd=digits::<5>(&p,w);let population=if exhaust{(0..p.to_u64().unwrap()).map(BigUint::from).collect()}else{cases(&p,&r,w)};let mut s=Stats::default();let mut digest=Sha256::new();let mut max_error=BigUint::zero();for b in population{let bd=digits::<5>(&b,w);let(q,d,q0,d0,correction)=prepare(bd,md,pd,w,&mut s);let q=integer(&q,w);let d=integer(&d,w);let q0=integer(&q0,w);let d0=integer(&d0,w);let full=&b*&r;let expected_q=&full/&p;let expected_d=&full%&p;assert!(q0<=expected_q);let error=&expected_q-&q0;assert!(error<=BigUint::one());max_error=max_error.max(error);assert_eq!(d0,&full-&q0*&p);assert!(d0< &p*2u8);assert_eq!(q,expected_q);assert_eq!(d,expected_d);assert_eq!(&b*&r,&q*&p+&d);s.max_q_bits=s.max_q_bits.max(q.bits());s.cases+=1;s.corrections[correction]+=1;let record=json!({"b":b.to_str_radix(16),"q0":q0.to_str_radix(16),"q":q.to_str_radix(16),"D_before":d0.to_str_radix(16),"D_after":d.to_str_radix(16)});if s.examples[correction].is_none(){s.examples[correction]=Some(record.clone());}digest.update(serde_json::to_vec(&record).unwrap());}assert!(s.corrections.iter().all(|&n|n>0));assert!(s.max_high<(1u64<<60)&&s.max_low<(1u64<<60));json!({"name":name,"modulus":p.to_str_radix(10),"digit_bits":w,"radix_bits":5*w,"reciprocal_digits":md,"cases":s.cases,"exhaustive_canonical_operands":exhaust,"corrections0_1":s.corrections,"maximum_quotient_error_before_correction":max_error.to_u64().unwrap(),"max_high_coefficient":s.max_high,"max_low_coefficient":s.max_low,"maximum_output_quotient_bits":s.max_q_bits,"examples":s.examples,"all_outputs_digest":format!("{:x}",digest.finalize()),"passed":true})}
fn main(){let out=format!("{RPATH}/model-result.json");assert!(!std::path::Path::new(&out).exists());let fields=[("Fq","21888242871839275222246405745257275088696311157297823662689037894645226208583"),("Fr","21888242871839275222246405745257275088548364400416034343698204186575808495617")];let mut rows=vec![run("exhaustive-base16",65537u64.into(),4,true)];for(name,p)in fields{rows.push(run(name,BigUint::parse_bytes(p.as_bytes(),10).unwrap(),52,false));}let cases=rows.iter().map(|v|v["cases"].as_u64().unwrap()).sum::<u64>();let result=json!({"passed":true,"rows":rows,"new_exact_quotient_and_remainder_cases":cases,"candidate_uses_machine_word_digits":true,"oracle":"Independent arbitraryprecision BigUint division and remainder; no SIMD/nativefield/proof timing", "source_IFMA_proxy":{"preparation_high_terms":44,"preparation_low_q_times_p":25,"preparation_total_excluding_root_decode":69,"conservative_ordinary_root_decode":105,"ordinary_product":105,"inherited_fixed_product":84,"ordinary_column":8400,"candidate_column_including_preparation_and_decode":8238,"removed":162},"fixed_prepared_payload_bytes_8lanes":640,"prime_constant_bytes":48,"native_or_latency_qualified":false,"proof_ledger_unchanged":33449,"production_adopted":false,"original_all8_goal_active":true});fs::write(out,serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("PASS{cases}newquotient/remaindercases; bothcorrectionbranches;69sourceprepIFMAs; no native performance orproofclaim");}
